/**
 * Adventure Mode RPG Progression, Combat Economy & 3-Branch Skill Tree (`AdventureProgression`)
 *
 * Strictly isolated to Adventure Mode (`game.isAdventureMode() === true`):
 *  - Leaves ALL VS Mode (`1v1`, `2v2_brawl`, `2v2_tag`) stats, cooldowns, mana, and finisher gauges 100% untouched.
 *  - Gives Adventure Mode its own grounded Level 1..10 RPG stats (`ADV HP`, `ATK PWR`, `SPIRIT`, `WARD`, `HASTE`).
 *  - Replaces VS passive mana/finisher charging with bespoke Dungeon Action-RPG systems:
 *      1. SKILLS (`PILLAR`): Powered by `Solar Spirit` (`0..100`), generated by landing Basic Attack combos & Dodges/Wards,
 *         plus `Combo Flow` cooldown shaving on Basic hits.
 *      2. ULTIMATE (`ECLIPSE NOVA`): Starts at `0%` and charges ONLY via magnetic `Soul Ember` drops from slain monsters
 *         and active Hit-Combo streaks (zero passive VS damage-taken rubberbanding).
 *      3. SUPER-ULTIMATE (`ASTRAL METEOR`): Starts at `0%` (`0 / 3 Astral Seals`) and charges ONLY via `Astral Relic Shards`
 *         dropped by Realm Clears, Elite Guardians, Boss Phase Breaks, and Ultimate Resonance.
 *  - Full 3-Branch, 9-Node Rankable Skill Tree (`Solar Wrath`, `Astral Awakening`, `Phoenix Aegis`) with live SP upgrades & respec.
 */

export const ADVENTURE_SKILL_TREE = [
  // =========================================================================
  // BRANCH I: SOLAR WRATH (Offense, Basic Fireball & Flame Pillar Mastery)
  // =========================================================================
  {
    id: 'wrath_1',
    branch: 'wrath',
    branchName: 'SOLAR WRATH',
    tier: 1,
    maxRank: 3,
    glyph: '🔥',
    name: 'IGNITED VOLLEY',
    summary: (r) =>
      `+${r * 15 || 15}% Basic Attack Power${r >= 2 ? ' • Every 2nd cast launches a Homing Seeker!' : ' (Rank 2: Homing Seeker bolt)'}`
  },
  {
    id: 'wrath_2',
    branch: 'wrath',
    branchName: 'SOLAR WRATH',
    tier: 2,
    maxRank: 2,
    glyph: '⚡',
    name: 'COMBUSTION FLOW',
    summary: (r) =>
      `Basic hits grant +${(r || 1) * 6} bonus Spirit & shave -${((r || 1) * 0.55).toFixed(2)}s off Skill CD`
  },
  {
    id: 'wrath_3',
    branch: 'wrath',
    branchName: 'SOLAR WRATH',
    tier: 3,
    maxRank: 2,
    glyph: '🌋',
    name: 'SEARING MASTERY',
    summary: (r) =>
      `Skill Spirit cost ${r === 2 ? '14' : r === 1 ? '22' : '22/14'} (from 32) & +${(r || 1) * 28}% Skill Damage`
  },

  // =========================================================================
  // BRANCH II: ASTRAL AWAKENING (Ultimate & Super-Ultimate Relic Mastery)
  // =========================================================================
  {
    id: 'astral_1',
    branch: 'astral',
    branchName: 'ASTRAL AWAKENING',
    tier: 1,
    maxRank: 3,
    glyph: '✦',
    name: 'SOUL HARVESTER',
    summary: (r) =>
      `+${(r || 1) * 25}% Ultimate charge from Soul Embers & Combos (+Boss hit charge)`
  },
  {
    id: 'astral_2',
    branch: 'astral',
    branchName: 'ASTRAL AWAKENING',
    tier: 2,
    maxRank: 2,
    glyph: '🌑',
    name: 'ECLIPSE OVERCHARGE',
    summary: (r) =>
      `+${(r || 1) * 28}% Overdrive Ultimate Damage & +${(r || 1) * 14}% bonus Astral Seal resonance`
  },
  {
    id: 'astral_3',
    branch: 'astral',
    branchName: 'ASTRAL AWAKENING',
    tier: 3,
    maxRank: 2,
    glyph: '☄️',
    name: 'CATACLYSM SOVEREIGN',
    summary: (r) =>
      `Unseals +${(r || 1) * 34}% Astral Relic immediately & +${(r || 1) * 35}% Supreme Ultimate Damage`
  },

  // =========================================================================
  // BRANCH III: PHOENIX AEGIS (Vitality, 3D Mobility & Sustain)
  // =========================================================================
  {
    id: 'aegis_1',
    branch: 'aegis',
    branchName: 'PHOENIX AEGIS',
    tier: 1,
    maxRank: 3,
    glyph: '🛡️',
    name: 'SUNFORGED VITALITY',
    summary: (r) =>
      `+${(r || 1) * 240} Max Adventure HP & +${(r || 1) * 7}% Solar Ward Damage Reduction`
  },
  {
    id: 'aegis_2',
    branch: 'aegis',
    branchName: 'PHOENIX AEGIS',
    tier: 2,
    maxRank: 2,
    glyph: '🪽',
    name: 'ZEPHYR STRIDE',
    summary: (r) =>
      `+${(r || 1) * 12}% 3D Move Speed & -${(r || 1) * 20}% Blink / Vault / Ward Cooldowns`
  },
  {
    id: 'aegis_3',
    branch: 'aegis',
    branchName: 'PHOENIX AEGIS',
    tier: 3,
    maxRank: 2,
    glyph: '☀️',
    name: 'UNDYING PHOENIX',
    summary: (r) =>
      `Ward & Blink heal +${(r || 1) * 45} bonus HP • Soul Embers restore +${(r || 1) * 5}% Max HP`
  }
];

export class AdventureProgression {
  constructor(adventure) {
    this.adventure = adventure;
    this.resetForNewCampaign();
  }

  resetForNewCampaign() {
    this.level = 1;
    this.maxLevel = 10;
    this.xp = 0;
    this.xpToNext = 115;

    // Start with 1 Skill Point at Lv.1 so players can customize their Adventure build immediately!
    this.skillPoints = 1;
    this.totalSpEarned = 1;

    this.ranks = {};
    for (const node of ADVENTURE_SKILL_TREE) {
      this.ranks[node.id] = 0;
    }

    // Dedicated Adventure Combat Resources (completely decoupled from VS PvP gauges!)
    this.spirit = 68;
    this.maxSpirit = 100;
    this.ultCharge = 0; // 0..100 (Solar Awakening — Ultimate)
    this.astralCharge = 0; // 0..100 (Astral Relic Seals — Super-Ultimate)

    this.comboHits = 0;
    this.comboTimer = 0;
    this.seekerShotCounter = 0;
  }

  getRank(nodeId) {
    return this.ranks[nodeId] || 0;
  }

  getBranchPointsSpent(branch) {
    let sum = 0;
    for (const node of ADVENTURE_SKILL_TREE) {
      if (node.branch === branch) {
        sum += this.ranks[node.id] || 0;
      }
    }
    return sum;
  }

  canUpgradeNode(nodeId) {
    const node = ADVENTURE_SKILL_TREE.find((n) => n.id === nodeId);
    if (!node) return false;
    const cur = this.getRank(nodeId);
    if (cur >= node.maxRank || this.skillPoints <= 0) return false;
    const branchSpent = this.getBranchPointsSpent(node.branch);
    if (node.tier === 2 && branchSpent < 1) return false;
    if (node.tier === 3 && branchSpent < 2) return false;
    return true;
  }

  upgradeNode(nodeId, player = null) {
    if (!this.canUpgradeNode(nodeId)) return false;
    const prevMaxHp = this.getComputedStats().maxHp;
    this.ranks[nodeId] = (this.ranks[nodeId] || 0) + 1;
    this.skillPoints = Math.max(0, this.skillPoints - 1);

    if (nodeId === 'astral_3') {
      this.gainAstralRelic(34, player, '★ ASTRAL SEAL UNLOCKED! ★');
    }

    if (player) {
      this.applyStatsToFighter(player, prevMaxHp);
      this.syncGaugesToPlayer(player);
    }
    return true;
  }

  refundAllSkillPoints(player = null) {
    let spent = 0;
    for (const node of ADVENTURE_SKILL_TREE) {
      spent += this.ranks[node.id] || 0;
      this.ranks[node.id] = 0;
    }
    if (spent <= 0) return false;
    this.skillPoints += spent;
    // Clamp Astral Charge if Cataclysm Sovereign bonus was refunded before being spent
    this.astralCharge = Math.min(this.astralCharge, 100);
    if (player) {
      const stats = this.getComputedStats();
      player.maxHp = stats.maxHp;
      player.hp = Math.min(player.hp, player.maxHp);
      this.syncGaugesToPlayer(player);
    }
    return true;
  }

  getComputedStats() {
    const lv = Math.max(1, this.level);
    const rWrath1 = this.getRank('wrath_1');
    const rWrath2 = this.getRank('wrath_2');
    const rWrath3 = this.getRank('wrath_3');
    const rAstral1 = this.getRank('astral_1');
    const rAstral2 = this.getRank('astral_2');
    const rAstral3 = this.getRank('astral_3');
    const rAegis1 = this.getRank('aegis_1');
    const rAegis2 = this.getRank('aegis_2');
    const rAegis3 = this.getRank('aegis_3');

    const maxHp = 1040 + (lv - 1) * 110 + rAegis1 * 240;
    const atkMult = 0.50 + (lv - 1) * 0.045 + rWrath1 * 0.15;
    const skillMult = 0.54 + (lv - 1) * 0.045 + rWrath1 * 0.08 + rWrath3 * 0.28;
    const ultMult = 0.50 + (lv - 1) * 0.04 + rAstral2 * 0.28;
    const superUltMult = 0.45 + (lv - 1) * 0.04 + rAstral3 * 0.35;

    const skillSpiritCost = rWrath3 >= 2 ? 14 : rWrath3 === 1 ? 22 : 32;
    const basicSpiritGain = 12 + rWrath2 * 6;
    const basicSkillCdShave = 0.35 + rWrath2 * 0.55;

    const ultGainMult = 1.0 + rAstral1 * 0.25;
    const bossHitUltGain = rAstral1 > 0 ? 0.5 + rAstral1 * 1.4 : 0.45;
    const ultResonanceAstral = 18 + rAstral2 * 14;

    const wardReduction = Math.min(0.42, 0.04 + (lv - 1) * 0.015 + rAegis1 * 0.07);
    const moveSpeedMult = 1.0 + rAegis2 * 0.12;
    const mobilityCdMult = Math.max(0.52, 1.0 - rAegis2 * 0.20);
    const evasiveHealBonus = rAegis3 * 45;
    const emberHealPct = rAegis3 * 0.05;

    return {
      maxHp,
      atkMult,
      skillMult,
      ultMult,
      superUltMult,
      skillSpiritCost,
      basicSpiritGain,
      basicSkillCdShave,
      ultGainMult,
      bossHitUltGain,
      ultResonanceAstral,
      wardReduction,
      moveSpeedMult,
      mobilityCdMult,
      evasiveHealBonus,
      emberHealPct,
      hasHomingSeeker: rWrath1 >= 2
    };
  }

  attachToFighter(player) {
    if (!player) return;
    if (!player._advOrig) {
      player._advOrig = {
        maxHp: player.maxHp,
        hp: player.hp,
        gainMana: player.gainMana.bind(player),
        gainFinisher: player.gainFinisher.bind(player),
        takeDamage: player.takeDamage.bind(player),
        heal: player.heal.bind(player)
      };
    }

    const stats = this.getComputedStats();
    player.maxHp = stats.maxHp;
    player.hp = stats.maxHp;
    player.mana = 0;
    player.finisherGauge = 0;

    // Intercept VS passive Mana & Finisher gains so Adventure Mode uses ONLY Soul Embers, Combos & Astral Relics!
    player.gainMana = () => {};
    player.gainFinisher = () => {};

    // Wrap Adventure Healing so flat PvP micro-heals scale naturally to Adventure HP + Undying Phoenix bonuses!
    player.heal = (amount, label = '') => {
      if (player.isDead || amount <= 0) return 0;
      const curStats = this.getComputedStats();
      let scaledAmt = Math.max(8, Math.round(amount * 0.72));
      if (player.state === 'DODGE' || player.state === 'CROUCH' || label.includes('WARD') || label.includes('BLINK') || label.includes('PARRY') || label.includes('GUARD') || label.includes('AEGIS')) {
        scaledAmt += curStats.evasiveHealBonus;
      }
      return player._advOrig.heal(scaledAmt, label);
    };

    // Wrap Adventure Incoming Damage for Solar Ward Armor Reduction + Flame Ward Spirit Counter!
    player.takeDamage = (amount, attacker, isCrit = false, knockX = 95, knockY = 0) => {
      if (player.isDead || player.isBenched) return;
      const curStats = this.getComputedStats();
      const wasDeflecting = Boolean(player.isDeflecting);
      const mitigated = Math.max(1, Math.round(amount * (1 - curStats.wardReduction)));
      player._advOrig.takeDamage(mitigated, attacker, isCrit, knockX, knockY);
      if (wasDeflecting) {
        this.gainSpirit(18);
      }
      this.syncGaugesToPlayer(player);
    };

    this.syncGaugesToPlayer(player);
  }

  detachFromFighter(player) {
    if (!player || !player._advOrig) return;
    player.maxHp = player._advOrig.maxHp;
    player.hp = Math.min(player.maxHp, player.hp);
    player.gainMana = player._advOrig.gainMana;
    player.gainFinisher = player._advOrig.gainFinisher;
    player.takeDamage = player._advOrig.takeDamage;
    player.heal = player._advOrig.heal;
    delete player._advOrig;
  }

  applyStatsToFighter(player, prevMaxHp = null) {
    if (!player) return;
    const stats = this.getComputedStats();
    const oldMax = prevMaxHp || player.maxHp || stats.maxHp;
    const deltaHp = Math.max(0, stats.maxHp - oldMax);
    player.maxHp = stats.maxHp;
    if (deltaHp > 0 && !player.isDead) {
      player.hp = Math.min(player.maxHp, player.hp + deltaHp);
    } else {
      player.hp = Math.min(player.maxHp, player.hp);
    }
  }

  syncGaugesToPlayer(player) {
    if (!player) return;
    player.mana = Math.max(0, Math.min(player.maxMana || 100, this.ultCharge));
    player.finisherGauge = Math.max(0, Math.min(player.maxFinisherGauge || 100, this.astralCharge));
  }

  gainSpirit(amount) {
    if (!Number.isFinite(amount) || amount === 0) return;
    this.spirit = Math.max(0, Math.min(this.maxSpirit, this.spirit + amount));
  }

  trySpendSkillSpirit() {
    const cost = this.getComputedStats().skillSpiritCost;
    if (this.spirit + 0.01 < cost) return false;
    this.spirit = Math.max(0, this.spirit - cost);
    return true;
  }

  gainAdventureUlt(amount, player = null) {
    if (!Number.isFinite(amount) || amount <= 0) return;
    const stats = this.getComputedStats();
    this.ultCharge = Math.max(0, Math.min(100, this.ultCharge + amount * stats.ultGainMult));
    if (player) this.syncGaugesToPlayer(player);
  }

  gainAstralRelic(rawAmount, player = null, bannerText = '') {
    if (!Number.isFinite(rawAmount) || rawAmount <= 0) return;
    this.astralCharge = Math.max(0, Math.min(100, this.astralCharge + rawAmount));
    if (player) {
      this.syncGaugesToPlayer(player);
      if (bannerText && this.adventure?.game?.vfx) {
        this.adventure.game.vfx.spawnDamageText(
          player.x,
          player.y - 172,
          0,
          true,
          bannerText,
          '#67e8f9'
        );
      }
    }
  }

  gainXp(amount, player = null) {
    if (!Number.isFinite(amount) || amount <= 0 || this.level >= this.maxLevel) return;
    this.xp += Math.round(amount);
    const g = this.adventure?.game;

    while (this.xp >= this.xpToNext && this.level < this.maxLevel) {
      this.xp -= this.xpToNext;
      const prevMaxHp = this.getComputedStats().maxHp;
      this.level++;
      this.skillPoints++;
      this.totalSpEarned++;
      this.xpToNext = Math.round(115 * Math.pow(1.32, this.level - 1));
      this.gainSpirit(35);

      if (player && !player.isDead) {
        this.applyStatsToFighter(player, prevMaxHp);
        const bonusHeal = Math.round(player.maxHp * 0.22);
        player.hp = Math.min(player.maxHp, player.hp + bonusHeal);
        if (g?.audio) g.audio.play('holy_hit', player.x);
        if (g?.vfx) {
          g.vfx.spawnShockwave(player.x, player.groundY - 8, 175, '#facc15', 0.45, true);
          g.vfx.spawnBurst(player.x, player.y - 92, 24, '#fde047', 260, { upBias: 145, size: 6 });
          g.vfx.spawnDamageText(
            player.x,
            player.y - 208,
            0,
            true,
            `★ LEVEL UP! LV.${this.level} (+1 SP) ★`,
            '#fde047'
          );
        }
      }
    }
  }

  scaleOutgoingDamage(rawAmount, attacker, monster, _isCrit = false) {
    if (!attacker || attacker.isMonster) return rawAmount;
    const stats = this.getComputedStats();
    const st = attacker.state;
    let mult = stats.atkMult;
    if (st === 'TRUE_ULTIMATE' || rawAmount >= 420) {
      mult = stats.superUltMult;
      if (monster?.isBoss) mult *= 1.18;
    } else if (st === 'ULTIMATE') {
      mult = stats.ultMult;
    } else if (st === 'SKILL' || (rawAmount >= 22 && rawAmount <= 44)) {
      mult = stats.skillMult;
    }

    // Colossal Boss Exposed Heart-Core Punish Bonus (+45% damage during Vulnerable Core Slump!)
    if (monster?.isBoss && (monster.vulnerableTimer || 0) > 0) {
      mult *= 1.45;
    }
    return Math.max(4, Math.round(rawAmount * mult));
  }

  onPlayerHitMonster(player, monster, _dealtDamage) {
    if (!player || player.isDead) return;
    const stats = this.getComputedStats();
    this.comboHits++;
    this.comboTimer = 3.0;

    const st = player.state;
    if (st === 'AUTO_ATTACK' || st === 'IDLE' || st === 'WALK' || st === 'CROUCH' || st === 'JUMP') {
      this.gainSpirit(stats.basicSpiritGain);
      if (player.skillCooldown > 0) {
        player.skillCooldown = Math.max(0, player.skillCooldown - stats.basicSkillCdShave);
      }
      const comboBonus = this.comboHits >= 8 ? 1.45 : this.comboHits >= 4 ? 1.2 : 1.0;
      const baseUltHit = monster?.isBoss ? stats.bossHitUltGain + 1.5 : 2.1;
      this.gainAdventureUlt(baseUltHit * comboBonus, player);
    } else if (st === 'SKILL') {
      const skillUltHit = monster?.isBoss ? stats.bossHitUltGain + 1.8 : 1.8;
      this.gainAdventureUlt(skillUltHit, player);
    }
  }

  onPlayerCastBasicAttack(player, target, game) {
    const stats = this.getComputedStats();
    if (!stats.hasHomingSeeker || !player || !game?.vfx) return;
    this.seekerShotCounter++;
    if (this.seekerShotCounter % 2 !== 0) return;

    const sx = player.x + player.facing * 44;
    const sy = player.y - 122;
    const tx = target ? target.x : sx + player.facing * 440;
    const ty = target ? (target.isColossalBoss ? target.y - 135 : target.y - 102) : sy;
    const dx = tx - sx;
    const dy = ty - sy;
    const len = Math.hypot(dx, dy) || 1;
    game.vfx.spawnProjectile({
      x: sx,
      y: sy,
      vx: (dx / len) * 690,
      vy: (dy / len) * 690 - 18,
      radius: 11,
      color: player.primaryColor || '#fde047',
      coreColor: '#ffffff',
      owner: player,
      damage: 58,
      type: 'fireball',
      isMeteor: false
    });
  }

  update(dt, player) {
    if (this.comboTimer > 0) {
      this.comboTimer = Math.max(0, this.comboTimer - dt);
      if (this.comboTimer <= 0) {
        this.comboHits = 0;
      }
    }
    // Gentle natural Solar Spirit focus regeneration (+5.0/sec)
    if (player && !player.isDead && this.spirit < this.maxSpirit) {
      this.gainSpirit(5.0 * dt);
    }
    if (player) {
      this.syncGaugesToPlayer(player);
    }
  }
}
